import { createOpenAPI } from "fumadocs-openapi/server";
import openapi from "@/public/openapi.json";

// The API reference pages (content/docs/developers/api, generated by
// `pnpm openapi:generate`) render public/openapi.json with fumadocs-openapi.

/** The document id the generated pages pass as `document`. */
export const API_DOCUMENT_ID = "qrdx";

/**
 * "Try it" sends requests to this site's /api/v1, the same routes as
 * api.qrdx.dev/v1: same-origin requests need no CORS (only the image API
 * allows cross-origin calls) and stay inside connect-src 'self'. The code
 * samples still show api.qrdx.dev (components/docs/api-page.client.tsx).
 */
export const TRY_IT_SERVER = {
  url: "/api/v1",
  description: "This site (Try it sends requests here)",
};

/** The published document, with the Try it server first. */
export function referenceDocument() {
  return {
    ...openapi,
    servers: [TRY_IT_SERVER, ...openapi.servers],
  };
}

export const apiReference = createOpenAPI({
  input: {
    // fumadocs reads the document type loosely; it is our generated JSON.
    [API_DOCUMENT_ID]: () => referenceDocument() as never,
  },
});
